import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for BeautifulSoup import
found_bs = False
for node in ast.walk(tree):
    if isinstance(node, ast.ImportFrom) and node.module == 'bs4':
        for name in node.names:
            if name.name == 'BeautifulSoup':
                found_bs = True

if not found_bs:
    raise AssertionError('Task 1: Missing from bs4 import BeautifulSoup')

# Check for BeautifulSoup() call with two arguments
found_soup = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'BeautifulSoup':
        if len(node.args) >= 2:
            # Check first arg is html_doc, second is 'html.parser'
            first_arg = ast.unparse(node.args[0])
            second_arg = ast.unparse(node.args[1])
            if 'html_doc' in first_arg and 'html.parser' in second_arg:
                found_soup = True

if not found_soup:
    raise AssertionError('Task 2: Missing BeautifulSoup(html_doc, \'html.parser\') call')

# Check for .find_all('a') call - specifically looking for tag 'a'
found_find_all = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'find_all':
        # Check first argument is 'a'
        if node.args:
            first_arg = ast.unparse(node.args[0])
            if "'a'" in first_arg or '"a"' in first_arg:
                found_find_all = True

if not found_find_all:
    raise AssertionError('Task 3: Missing soup.find_all(\'a\') call with the correct tag')

# Check for for loop
found_loop = False
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        found_loop = True

if not found_loop:
    raise AssertionError('Task 4: Missing for loop to iterate through links')

# Check for href attribute access with correct syntax link['href']
found_href = False
for node in ast.walk(tree):
    if isinstance(node, ast.Subscript):
        # Check if it's a subscript access like something['href']
        if isinstance(node.slice, ast.Constant) and node.slice.value == 'href':
            found_href = True
        elif isinstance(node.slice, ast.Str) and node.slice.s == 'href':  # For older Python
            found_href = True

if not found_href:
    raise AssertionError('Task 4: Missing attribute access with [\'href\']')

print('TEST_PASSED')
